sp_widget.client_script:
api.controller = function() {

    var c = this;


    /* =========================================
       HOME
       ========================================= */

    c.goHome = function() {

        window.location.href =
            "?id=cfms_home";

    };


    /* =========================================
       ASSIGNED TICKETS
       ========================================= */

    c.assignedTickets = function() {

        window.location.href =
            "?id=cfms_assigned";

    };


    /* =========================================
       RECORDS
       ========================================= */

    c.records = function() {

        window.location.href =
            "?id=cfms_records";

    };


    /* =========================================
       REPORTS
       ========================================= */

    c.reports = function() {

        /*
         * Create cfms_reports later if you
         * want a separate Reports page.
         */

        window.location.href =
            "?id=cfms_records";

    };


    /* =========================================
       FEEDBACK
       ========================================= */

    c.feedback = function() {

        /*
         * Manager can currently view the
         * records page where feedback-related
         * information can be displayed.
         */

        window.location.href =
            "?id=cfms_records";

    };

};

sp_widget.css:
/* =========================================
   CFMS MANAGER HOME
   ========================================= */

.cfms-manager {

  min-height: 100vh;

  background: #f0fbfc;

  padding: 30px;

  font-family:
    'Segoe UI',
    Tahoma,
    Geneva,
    Verdana,
    sans-serif;

  color: #263238;
}


/* =========================================
   HEADER
   ========================================= */

.manager-header {

  background:
    linear-gradient(
      135deg,
      #00acc1,
      #4dd0e1
    );

  color: white;

  border-radius: 20px;

  padding: 28px 32px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  margin-bottom: 25px;

  box-shadow:
    0 8px 25px
    rgba(0, 172, 193, 0.18);
}


.header-content {

  display: flex;

  align-items: center;

  gap: 17px;
}


.header-icon {

  width: 58px;

  height: 58px;

  background: rgba(255,255,255,0.18);

  border-radius: 15px;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 28px;
}


.manager-header h1 {

  margin: 0 0 6px;

  font-size: 29px;

  font-weight: 700;
}


.manager-header p {

  margin: 0;

  font-size: 14px;

  opacity: 0.95;
}


.home-btn {

  border: none;

  background: white;

  color: #008c9e;

  padding: 11px 18px;

  border-radius: 10px;

  font-weight: 600;

  cursor: pointer;

  transition: 0.2s;
}


.home-btn:hover {

  transform: translateY(-2px);

  box-shadow:
    0 5px 15px
    rgba(0,0,0,0.1);
}


/* =========================================
   ALERT
   ========================================= */

.alert {

  padding: 14px 18px;

  border-radius: 10px;

  margin-bottom: 20px;

  font-weight: 600;
}


.error-alert {

  background: #ffebee;

  color: #c62828;

  border: 1px solid #ef9a9a;
}


/* =========================================
   WELCOME
   ========================================= */

.welcome-card {

  background: white;

  border-radius: 18px;

  padding: 27px 30px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  margin-bottom: 25px;

  box-shadow:
    0 5px 18px
    rgba(38,50,56,0.06);
}


.welcome-label {

  color: #0097a7;

  font-size: 11px;

  font-weight: 800;

  letter-spacing: 1px;
}


.welcome-text h2 {

  margin: 7px 0 7px;

  font-size: 24px;
}


.welcome-text p {

  margin: 0;

  color: #78909c;

  font-size: 14px;
}


.welcome-icon {

  width: 72px;

  height: 72px;

  border-radius: 18px;

  background: #e0f7fa;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 34px;
}


/* =========================================
   STATISTICS
   ========================================= */

.stats-grid {

  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 18px;

  margin-bottom: 25px;
}


.stat-card {

  background: white;

  border-radius: 16px;

  padding: 21px;

  display: flex;

  align-items: center;

  gap: 15px;

  box-shadow:
    0 4px 15px
    rgba(38,50,56,0.06);

  border: 1px solid #e4f2f4;
}


.stat-icon {

  width: 51px;

  height: 51px;

  border-radius: 13px;

  background: #e0f7fa;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 23px;
}


.stat-content span {

  display: block;

  color: #78909c;

  font-size: 12px;

  margin-bottom: 5px;
}


.stat-content strong {

  font-size: 26px;

  color: #263238;
}


/* =========================================
   DASHBOARD GRID
   ========================================= */

.dashboard-grid {

  display: grid;

  grid-template-columns:
    1fr 1fr;

  gap: 20px;

  margin-bottom: 28px;
}


.dashboard-card,
.recent-card {

  background: white;

  border-radius: 17px;

  padding: 25px;

  box-shadow:
    0 5px 20px
    rgba(38,50,56,0.06);
}


.card-header {

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding-bottom: 18px;

  border-bottom: 1px solid #edf5f6;
}


.card-header h3 {

  margin: 0 0 5px;

  font-size: 18px;
}


.card-header p {

  margin: 0;

  color: #78909c;

  font-size: 12px;
}


.card-icon {

  width: 42px;

  height: 42px;

  background: #e0f7fa;

  border-radius: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 20px;
}


/* =========================================
   PRIORITY
   ========================================= */

.priority-list {

  padding-top: 8px;
}


.priority-item {

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 14px 5px;

  border-bottom: 1px solid #f0f5f6;
}


.priority-item:last-child {

  border-bottom: none;
}


.priority-left {

  display: flex;

  align-items: center;

  gap: 10px;

  font-size: 14px;
}


.priority-item strong {

  font-size: 15px;
}


.priority-dot {

  width: 10px;

  height: 10px;

  border-radius: 50%;
}


.priority-dot.critical {
  background: #e53935;
}


.priority-dot.high {
  background: #fb8c00;
}


.priority-dot.medium {
  background: #fdd835;
}


.priority-dot.low {
  background: #43a047;
}


/* =========================================
   GROUPS
   ========================================= */

.group-list {

  padding-top: 7px;
}


.group-item {

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 11px 3px;

  border-bottom: 1px solid #f0f5f6;
}


.group-item:last-child {

  border-bottom: none;
}


.group-info {

  display: flex;

  align-items: center;

  gap: 11px;
}


.group-avatar {

  width: 38px;

  height: 38px;

  border-radius: 10px;

  background: #e0f7fa;

  color: #008c9e;

  display: flex;

  align-items: center;

  justify-content: center;

  font-weight: 700;
}


.group-info strong {

  display: block;

  font-size: 13px;
}


.group-info span {

  display: block;

  color: #90a4ae;

  font-size: 11px;

  margin-top: 3px;
}


.group-count {

  font-size: 14px;

  font-weight: 700;

  color: #008c9e;
}


/* =========================================
   QUICK ACTIONS
   ========================================= */

.quick-section {

  margin-bottom: 25px;
}


.section-heading {

  margin-bottom: 15px;
}


.section-heading h2 {

  margin: 0 0 5px;

  font-size: 21px;
}


.section-heading p {

  margin: 0;

  color: #78909c;

  font-size: 13px;
}


.action-grid {

  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 17px;
}


.action-card {

  background: white;

  border-radius: 15px;

  padding: 21px;

  cursor: pointer;

  display: flex;

  gap: 13px;

  border: 1px solid #e3f2f4;

  box-shadow:
    0 4px 14px
    rgba(38,50,56,0.05);

  transition: 0.2s;
}


.action-card:hover {

  transform: translateY(-4px);

  border-color: #4dd0e1;

  box-shadow:
    0 9px 22px
    rgba(0,172,193,0.12);
}


.action-icon {

  width: 45px;

  height: 45px;

  min-width: 45px;

  border-radius: 12px;

  background: #e0f7fa;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 21px;
}


.action-content h3 {

  margin: 0 0 5px;

  font-size: 14px;
}


.action-content p {

  margin: 0 0 10px;

  color: #78909c;

  font-size: 11px;

  line-height: 1.5;
}


.action-content span {

  color: #0097a7;

  font-size: 11px;

  font-weight: 700;
}


/* =========================================
   RECENT REQUESTS
   ========================================= */

.recent-card {

  margin-bottom: 25px;
}


.view-all {

  border: none;

  background: transparent;

  color: #0097a7;

  font-size: 12px;

  font-weight: 700;

  cursor: pointer;
}


.request-list {

  padding-top: 5px;
}


.request-row {

  display: flex;

  justify-content: space-between;

  align-items: center;

  gap: 20px;

  padding: 16px 4px;

  border-bottom: 1px solid #edf5f6;
}


.request-row:last-child {

  border-bottom: none;
}


.request-info {

  display: flex;

  flex-direction: column;

  gap: 4px;
}


.request-number {

  color: #0097a7;

  font-size: 11px;

  font-weight: 700;
}


.request-info strong {

  font-size: 13px;

  font-weight: 600;
}


.request-caller {

  color: #90a4ae;

  font-size: 11px;
}


.request-right {

  display: flex;

  align-items: center;

  gap: 8px;
}


.status-badge,
.priority-badge {

  padding: 6px 10px;

  border-radius: 20px;

  font-size: 10px;

  font-weight: 700;

  white-space: nowrap;
}


.status-open {

  background: #fff3e0;

  color: #ef6c00;
}


.status-progress {

  background: #e3f2fd;

  color: #1565c0;
}


.status-resolved {

  background: #e8f5e9;

  color: #2e7d32;
}


.priority-critical {

  background: #ffebee;

  color: #c62828;
}


.priority-high {

  background: #fff3e0;

  color: #ef6c00;
}


.priority-medium {

  background: #fffde7;

  color: #827717;
}


.priority-low {

  background: #e8f5e9;

  color: #2e7d32;
}


/* =========================================
   EMPTY
   ========================================= */

.mini-empty {

  padding: 30px 10px;

  text-align: center;

  color: #90a4ae;

  font-size: 13px;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 1050px) {

  .stats-grid {

    grid-template-columns:
      repeat(2, 1fr);
  }

  .action-grid {

    grid-template-columns:
      repeat(2, 1fr);
  }

}


@media (max-width: 800px) {

  .cfms-manager {

    padding: 15px;
  }

  .manager-header {

    flex-direction: column;

    align-items: flex-start;

    gap: 15px;
  }

  .dashboard-grid {

    grid-template-columns: 1fr;
  }

}


@media (max-width: 600px) {

  .stats-grid {

    grid-template-columns: 1fr;
  }

  .action-grid {

    grid-template-columns: 1fr;
  }

  .welcome-card {

    align-items: flex-start;
  }

  .welcome-icon {

    display: none;
  }

  .request-row {

    align-items: flex-start;

    flex-direction: column;
  }

  .request-right {

    justify-content: flex-start;
  }

}

sp_widget.script:
(function() {

    data.userName = gs.getUserDisplayName();

    data.totalRequests = 0;
    data.activeRequests = 0;
    data.resolvedRequests = 0;

    data.averageRating = "0.0";

    data.criticalCount = 0;
    data.highCount = 0;
    data.mediumCount = 0;
    data.lowCount = 0;

    data.groups = [];
    data.recentRequests = [];

    data.error = "";


    /* =========================================
       SECURITY
       ========================================= */

    if (!gs.isLoggedIn()) {

        data.redirect = "cfms_login";

        return;
    }


    if (
        !gs.hasRole("cfms_manager") &&
        !gs.hasRole("admin")
    ) {

        data.error =
            "You are not authorized to access the Manager Portal.";

        data.redirect =
            "cfms_home";

        return;
    }


    /* =========================================
       INCIDENT DATA
       ========================================= */

    var groupMap = {};


    var gr = new GlideRecord("incident");

    gr.orderByDesc("sys_created_on");

    gr.query();


    while (gr.next()) {

        data.totalRequests++;


        var state =
            gr.getValue("state");


        /* -----------------------------------------
           ACTIVE / RESOLVED
           ----------------------------------------- */

        if (
            state == "6" ||
            state == "7"
        ) {

            data.resolvedRequests++;

        } else {

            data.activeRequests++;

        }


        /* -----------------------------------------
           PRIORITY
           ----------------------------------------- */

        var priority =
            gr.getValue("priority");


        if (priority == "1") {

            data.criticalCount++;

        } else if (priority == "2") {

            data.highCount++;

        } else if (priority == "3") {

            data.mediumCount++;

        } else if (priority == "4") {

            data.lowCount++;

        }


        /* -----------------------------------------
           ASSIGNMENT GROUP
           ----------------------------------------- */

        var groupID =
            gr.getValue("assignment_group");

        var groupName =
            gr.getDisplayValue("assignment_group");


        if (
            groupID &&
            groupName
        ) {

            if (!groupMap[groupID]) {

                groupMap[groupID] = {

                    name: groupName,

                    count: 0

                };

            }

            groupMap[groupID].count++;

        }


        /* -----------------------------------------
           RECENT REQUESTS
           ----------------------------------------- */

        if (
            data.recentRequests.length < 6
        ) {

            var stateText =
                gr.getDisplayValue("state");


            var statusClass =
                "status-open";


            if (state == "2") {

                statusClass =
                    "status-progress";

            } else if (
                state == "6" ||
                state == "7"
            ) {

                statusClass =
                    "status-resolved";

            }


            var priorityText =
                gr.getDisplayValue("priority");


            var priorityClass =
                "priority-medium";


            if (priority == "1") {

                priorityText =
                    "Critical";

                priorityClass =
                    "priority-critical";

            } else if (priority == "2") {

                priorityText =
                    "High";

                priorityClass =
                    "priority-high";

            } else if (priority == "3") {

                priorityText =
                    "Medium";

                priorityClass =
                    "priority-medium";

            } else if (priority == "4") {

                priorityText =
                    "Low";

                priorityClass =
                    "priority-low";

            }


            data.recentRequests.push({

                sys_id:
                    gr.getUniqueValue(),

                number:
                    gr.getValue("number"),

                short_description:
                    gr.getValue(
                        "short_description"
                    ),

                caller:
                    gr.getDisplayValue(
                        "caller_id"
                    ),

                state:
                    stateText,

                stateValue:
                    state,

                statusClass:
                    statusClass,

                priority:
                    priorityText,

                priorityClass:
                    priorityClass,

                created:
                    gr.getDisplayValue(
                        "sys_created_on"
                    )

            });

        }

    }


    /* =========================================
       CONVERT GROUP MAP TO ARRAY
       ========================================= */

    for (var groupID in groupMap) {

        if (
            groupMap.hasOwnProperty(groupID)
        ) {

            var groupName =
                groupMap[groupID].name;


            var initial =
                groupName
                .substring(0, 1)
                .toUpperCase();


            data.groups.push({

                name:
                    groupName,

                count:
                    groupMap[groupID].count,

                initial:
                    initial

            });

        }

    }


    /* =========================================
       FEEDBACK RATING
       ========================================= */

    /*
     * The CFMS feedback table created earlier
     * is u_cfms_feedback.
     */

    var feedback =
        new GlideRecord("u_cfms_feedback");


    if (feedback.isValid()) {

        var totalRating = 0;

        var ratingCount = 0;


        feedback.query();


        while (feedback.next()) {

            var rating =
                parseInt(
                    feedback.getValue(
                        "u_rating"
                    ),
                    10
                );


            if (!isNaN(rating)) {

                totalRating += rating;

                ratingCount++;

            }

        }


        if (ratingCount > 0) {

            data.averageRating =
                (
                    totalRating /
                    ratingCount
                ).toFixed(1);

        }

    }

})();
